#include <cstddef>

// Owns heap memory, but relies on the compiler-generated copy and move,
// which copy the raw pointer. Implement the rule of five.
class Buffer {
 public:
  explicit Buffer(std::size_t n) : size_(n), data_(new int[n]()) {}
  ~Buffer() { delete[] data_; }

  std::size_t size() const { return size_; }
  int* data() { return data_; }
  const int* data() const { return data_; }
  int& operator[](std::size_t i) { return data_[i]; }
  const int& operator[](std::size_t i) const { return data_[i]; }

 private:
  std::size_t size_;
  int* data_;
};

harness:
#include <type_traits>
#include <utility>
#include <vector>

TEST("a new buffer is zero-filled") {
  Buffer b(4);
  CHECK_EQ(b.size(), std::size_t{4});
  for (std::size_t i = 0; i < 4; ++i) CHECK_EQ(b[i], 0);
}

TEST("copy constructor makes a deep copy") {
  Buffer a(3);
  a[0] = 7;
  Buffer b(a);
  b[0] = 9;
  CHECK_EQ(a[0], 7);
  CHECK_EQ(b[0], 9);
  CHECK(a.data() != b.data());
}

TEST("copy assignment works between different sizes") {
  Buffer a(2);
  a[1] = 5;
  Buffer b(10);
  b = a;
  CHECK_EQ(b.size(), std::size_t{2});
  CHECK_EQ(b[1], 5);
  b[1] = 6;
  CHECK_EQ(a[1], 5);
}

TEST("self-assignment is safe") {
  Buffer a(3);
  a[2] = 4;
  Buffer& alias = a;
  a = alias;
  CHECK_EQ(a.size(), std::size_t{3});
  CHECK_EQ(a[2], 4);
}

TEST("move constructor steals the memory") {
  Buffer a(5);
  a[0] = 1;
  int* p = a.data();
  Buffer b(std::move(a));
  CHECK(b.data() == p);
  CHECK_EQ(b[0], 1);
  CHECK_EQ(a.size(), std::size_t{0});
  CHECK(a.data() == nullptr);
}

TEST("move assignment steals and frees the old memory") {
  Buffer a(5);
  int* p = a.data();
  Buffer b(2);
  b = std::move(a);
  CHECK(b.data() == p);
  CHECK_EQ(b.size(), std::size_t{5});
  CHECK_EQ(a.size(), std::size_t{0});
  CHECK(a.data() == nullptr);
}

TEST("moves are noexcept") {
  CHECK(std::is_nothrow_move_constructible_v<Buffer>);
  CHECK(std::is_nothrow_move_assignable_v<Buffer>);
}

TEST("works inside a growing std::vector") {
  std::vector<Buffer> v;
  for (int i = 0; i < 20; ++i) {
    v.emplace_back(3);
    v.back()[0] = i;
  }
  int sum = 0;
  for (const auto& b : v) sum += b[0];
  CHECK_EQ(sum, 190);
}

