#include <algorithm>
#include <cstddef>
#include <utility>

class Buffer {
 public:
  explicit Buffer(std::size_t n) : size_(n), data_(n ? new int[n]() : nullptr) {}
  ~Buffer() { delete[] data_; }

  // Copy: allocate our own memory and copy the elements.
  Buffer(const Buffer& other) : size_(other.size_), data_(other.size_ ? new int[other.size_] : nullptr) {
    std::copy(other.data_, other.data_ + size_, data_);
  }

  // Move: take the other buffer's memory and leave it empty.
  Buffer(Buffer&& other) noexcept
      : size_(std::exchange(other.size_, 0)), data_(std::exchange(other.data_, nullptr)) {}

  // Copy-and-swap: `other` is a copy (or a move) made by the caller, so this one
  // operator handles copy assignment, move assignment and self-assignment, and it
  // can't leave *this half-modified if the copy throws.
  Buffer& operator=(Buffer other) noexcept {
    swap(other);
    return *this;
  }

  void swap(Buffer& other) noexcept {
    std::swap(size_, other.size_);
    std::swap(data_, other.data_);
  }

  std::size_t size() const { return size_; }
  int* data() { return data_; }
  const int* data() const { return data_; }
  int& operator[](std::size_t i) { return data_[i]; }
  const int& operator[](std::size_t i) const { return data_[i]; }

 private:
  std::size_t size_;
  int* data_;
};
